create table if not exists public.ils_professional_assignment_e2e_preflight (id uuid primary key default gen_random_uuid(),path_code text not null unique default 'PROFESSIONAL_ASSIGNMENT_E2E',synthetic_only boolean not null default true,real_professional_assignment_allowed boolean not null default false,real_professional_identity_allowed boolean not null default false,customer_data_allowed boolean not null default false,real_work_offer_allowed boolean not null default false,payout_invocation_allowed boolean not null default false,external_execution_allowed boolean not null default false,authorization_level text not null default 'SECURITY_REVIEW',status text not null default 'READY' check(status in ('READY','HOLD','FAIL')),created_at timestamptz not null default now()); alter table public.ils_professional_assignment_e2e_preflight enable row level security; alter table public.ils_professional_assignment_e2e_preflight force row level security; revoke all on public.ils_professional_assignment_e2e_preflight from public,anon,authenticated; insert into public.ils_professional_assignment_e2e_preflight default values on conflict(path_code) do nothing; create or replace function public.ils_professional_assignment_e2e_preflight_check() returns table(status text,violations integer,real_professional_assignment_allowed boolean,real_professional_identity_allowed boolean,customer_data_allowed boolean,real_work_offer_allowed boolean,payout_invocation_allowed boolean,external_execution_allowed boolean) language sql security definer set search_path=public as $$ select case when synthetic_only and not real_professional_assignment_allowed and not real_professional_identity_allowed and not customer_data_allowed and not real_work_offer_allowed and not payout_invocation_allowed and not external_execution_allowed then 'READY' else 'FAIL' end,(case when synthetic_only then 0 else 1 end+case when real_professional_assignment_allowed then 1 else 0 end+case when real_professional_identity_allowed then 1 else 0 end+case when customer_data_allowed then 1 else 0 end+case when real_work_offer_allowed then 1 else 0 end+case when payout_invocation_allowed then 1 else 0 end+case when external_execution_allowed then 1 else 0 end),real_professional_assignment_allowed,real_professional_identity_allowed,customer_data_allowed,real_work_offer_allowed,payout_invocation_allowed,external_execution_allowed from public.ils_professional_assignment_e2e_preflight where path_code='PROFESSIONAL_ASSIGNMENT_E2E'; $$; revoke all on function public.ils_professional_assignment_e2e_preflight_check() from public,anon,authenticated; grant execute on function public.ils_professional_assignment_e2e_preflight_check() to service_role;